      })),
    ),
  )
  .handle(backupFlow);

const renewals = H.lane('certificate-renewals')
  .of(CertificateRenewal)
  .from(
    schedule<RenewalData>({ cron: '0 4 * * 1' }, tick =>
      domains.map(domain => ({
        key: `${domain}@${tick.now.toISOString().slice(0, 10)}`,
        data: { domain },
      })),
    ),
  )
  .handle(renewalFlow);

