      .recall(Experience, Taste)
      .use(
        gitWorktreeIsolation({ root: 'coding/.worktrees', baseBranch: 'main' }),
        fileLeaseGuard(),
        stopCommandHook('npm run check', { timeoutMs: 600000 }),
      ),
  )
  .model(builderModels);
